mapper.select:
select id, rule_id, rule_test_info, rule_type, create_user, rule_count, sample_count, finish_time, test_status, if(test_status = 1, '已完成', if(test_status = 2,'已失败', "未开始")) as testStatusText, create_time, update_time from report_rule_test_data where 1=1
and create_user in
#{item}
AND rule_test_info LIKE CONCAT('%', #{ruleTestInfo}, '%')
AND test_status = #{testStatus}
AND rule_type = #{ruleType}
order by create_time desc
